#include<bits/stdc++.h>
using namespace std;using U=uint64_t;const int N=216+4*216;int pairix[4][4],cap[N];vector<int>feat[1296];struct op{vector<pair<int,int>> v;int w[4];};op options[12][48];vector<int>hit[12][N];U masks[12][N][5];int pc(U u){return __builtin_popcountll(u);}int ix(U u){return __builtin_ctzll(u);}int lev[12];uint64_t nodes;
bool go(U done,array<U,12> dom){++nodes;for(int j=0;j<12;j++)if(!(done>>j&1)){U s=dom[j];for(U z=s;z;z&=z-1){int p=ix(z);for(auto [t,c]:options[j][p].v)if(cap[t]<c){s^=1ull<<p;break;}}if(!s)return false;dom[j]=s;}
 while(1){bool change=false;int mins[12],maxs[12];for(int t=0;t<216;t++){int lo=0,hi=0;for(int j=0;j<12;j++)if(!(done>>j&1)){int mn=0,mx=4;while(!(dom[j]&masks[j][t][mn]))mn++;while(!(dom[j]&masks[j][t][mx]))mx--;lo+=(mins[j]=mn);hi+=(maxs[j]=mx);}if(lo>cap[t]||hi<cap[t])return false;if(lo==hi)continue;for(int j=0;j<12;j++)if(!(done>>j&1)){int a=max(mins[j],cap[t]-hi+maxs[j]),b=min(maxs[j],cap[t]-lo+mins[j]);U w=0;for(int k=a;k<=b;k++)w|=masks[j][t][k];U v=dom[j]&w;if(v!=dom[j]){dom[j]=v;change=true;if(!v)return false;}}}if(!change)break;}
 if(done==4095)return true;int j=-1;for(int i=0;i<12;i++)if(!(done>>i&1)&&(j<0||pc(dom[i])<pc(dom[j])))j=i;
 for(U z=dom[j];z;z&=z-1){int q=ix(z);auto &o=options[j][q];for(auto [t,c]:o.v)cap[t]-=c;lev[j]=q;if(go(done|(1<<j),dom))return true;for(auto [t,c]:o.v)cap[t]+=c;}return false;}
int main(int argc,char**av){int num=0;for(int i=0;i<4;i++)for(int j=i+1;j<4;j++)pairix[i][j]=num++;for(int w=0;w<1296;w++){int a=w,v[4];for(auto &s:v)s=a%6,a/=6;for(int i=0;i<4;i++)for(int j=i+1;j<4;j++)feat[w].push_back(pairix[i][j]*36+6*v[i]+v[j]);for(int i=0;i<4;i++){int q=0;for(int j=0;j<4;j++)if(j!=i)q=6*q+v[j];feat[w].push_back(216+216*i+q);}}
 vector<array<int,4>>P;array<int,4>pp={0,1,2,3};do{if((pp[0]^pp[3])!=3)P.push_back(pp);}while(next_permutation(pp.begin(),pp.end()));int g=0;
 for(int i=0;i<3;i++)for(int s=0;s<4;s++)for(int t=s+1;t<4;t++){if((s==0&&t==1)||(s==2&&t==3))continue;int h[2],q=0;for(int k=0;k<4;k++)if(k!=s&&k!=t)h[q++]=k;int R[4];q=0;for(int x=0;x<6;x++)if(x/2!=i)R[q++]=x;int ct=0;for(auto p:P)for(auto z:P){if(p[0]/2==z[0]/2||p[1]/2==z[1]/2||p[2]/2==z[2]/2||p[3]/2==z[3]/2)continue;map<int,int>cnt;op &o=options[g][ct];for(int j=0;j<4;j++){int v[4];v[s]=2*i+j/2;v[t]=2*i+j%2;v[h[0]]=R[p[j]];v[h[1]]=R[z[j]];int w=v[0]+6*(v[1]+6*(v[2]+6*v[3]));o.w[j]=w;for(int t:feat[w])cnt[t]++;}o.v.assign(cnt.begin(),cnt.end());for(int t=0;t<N;t++)masks[g][t][cnt[t]]|=1ull<<ct;ct++;}assert(ct==48);g++;}assert(g==12);
 ifstream f("double.dat");int w,idx=0;while(f>>w){bool active=argc==1||atoi(av[1])==idx;for(int t=0;t<N;t++)cap[t]=t>=216?1:2-(t%36/12==t%6/2);int ww[12];ww[0]=w;for(int j=1;j<12;j++)f>>ww[j];for(int x:ww)for(int t:feat[x])cap[t]--;array<U,12>dom;dom.fill((1ull<<48)-1);nodes=0;if(active){bool sat=go(0,dom);cout<<idx<<" "<<sat<<" "<<nodes;if(sat){for(int j:ww)cout<<" "<<j;for(int k=0;k<12;k++)for(int j:options[k][lev[k]].w)cout<<" "<<j;}cout<<endl;}idx++;}}
